import "core-js/modules/es6.function.name";
import "core-js/modules/web.dom.iterable";
import * as echarts from 'echarts';
import Tabs from "../../components/dataPickerTabs/index.vue";
import { queryProcessConsumeTime, queryNodeConsumeTimeByProcessKey } from '@/api/workflow/analyse/processTimeAnalysis';
import * as _ from 'lodash';
var resizeObserve = null;
export default {
  name: 'ProcessTimeAnalysis',
  components: {
    Tabs: Tabs
  },
  data: function data() {
    return {
      tabsShow: {
        day: false,
        month: true,
        quarter: true,
        year: true,
        auto: false
      },
      options: [{
        value: '5',
        label: '前5名'
      }, {
        value: '10',
        label: '前10名'
      }, {
        value: '15',
        label: '前15名'
      }, {
        value: '20',
        label: '前20名'
      }],
      checked: false,
      isList: false,
      // 是否展示列表
      myChart: null,
      // 环图
      doughnutData: [],
      // 环图数据
      consumeTimeListData: [],
      // 消耗时间列表数据
      consumeTimeByKeyListData: [],
      //下钻列表数据
      copyData: [],
      // 下钻列表数据备份
      listParam: {},
      // 下钻列表参数
      dialogTableVisible: false,
      // 下钻列表是否弹出
      searchContent: '',
      // 搜索内容
      loading: false,
      current: 1,
      pageSize: 10,
      total: 10,
      // 查询条件
      choiceTime: {
        statisType: 'month',
        // 统计类型
        autoStartTime: null,
        // 自定义开始时间
        autoEndTime: null,
        // 自定义结束时间
        dayTime: null,
        // 按天统计时间
        monthMonth: "".concat(new Date().getFullYear(), "-").concat(new Date().getMonth() + 1),
        // 按月统计的月份值 2022-05
        quarterYear: null,
        // 按季度统计的年份值
        quarterQuarter: null,
        // 按季度统计的季度值
        yearYear: null,
        // 按年份统计的年份值
        size: '5'
      },
      isGetResult: false,
      // 是否获取到查询结果
      isLoading: false,
      processName: '',
      // 流程名称
      remarks: '统计特定时间内平均耗时排行前N的流程，对流程进行监控。'
    };
  },
  computed: {
    doughnutOption: function doughnutOption() {
      // const this = this;
      var data = [];
      this.doughnutData.forEach(function (item) {
        var obj = {};
        obj.value = item.processDate;
        obj.name = item.processName;
        obj.processKey = item.processKey;
        data.push(obj);
      });
      return {
        color: ['#2794F8', '#FFBB00', '#EE7B4E', '#52C566', '#6F5EF9', '#6DC8EC', '#945FB9', '#FF9845', '#1E9493', '#FF99C3', '#BDD2FD', '#BDD2FD', '#5AD8A6', '#BDEFDB', '#5D7092', '#C2C8D5', '#F6BD16', '#FBE5A2', '#E8684A', '#F6C3B7'],
        tooltip: {
          trigger: 'item',
          borderWidth: 0,
          backgroundColor: 'rgba(111, 111, 111, 1)',
          textStyle: {
            color: '#fff',
            fontWeight: '400'
          },
          confine: true
        },
        legend: {
          type: 'scroll',
          top: '16',
          right: 0,
          icon: 'circle',
          itemWidth: 9,
          itemHeight: 9,
          textStyle: {
            color: '#8C8C8C'
          },
          padding: 0,
          formatter: function formatter(name) {
            return echarts.format.truncateText(name, 100, '12px', '...');
          },
          tooltip: {
            show: false
          }
        },
        series: [{
          type: 'pie',
          minAngle: 3,
          radius: ['35%', '55%'],
          avoidLabelOverlap: true,
          itemStyle: {
            borderColor: '#fff',
            borderWidth: 2
          },
          top: 36,
          label: {
            show: true,
            color: '#545672',
            formatter: '{b}\n{c}h',
            padding: [5, 5, 5, 5],
            lineHeight: 17
          },
          labelLine: {
            show: true,
            length: 40,
            length2: 60,
            lineStyle: {
              width: 1,
              color: '#979797'
            }
          },
          data: data
        }]
      };
    }
  },
  watch: {
    doughnutOption: function doughnutOption() {
      this.drawDoughnut();
    }
  },
  mounted: function mounted() {
    var _this = this;
    // const this = this;
    this.doughnutDataLoad(this.choiceTime); //加载环图数据并重绘环图
    this.consumeTimeListLoad(this.choiceTime); //加载列表数据
    resizeObserve = new ResizeObserver(function () {
      if (_this.myChart) _this.myChart.resize();
    });
    resizeObserve.observe(document.getElementById('processOverviewContent'));
  },
  beforeUnmount: function beforeUnmount() {
    resizeObserve.disconnect();
  },
  methods: {
    // 每页显示几条数据
    handleSizeChange: function handleSizeChange(value) {
      // const this = this;
      this.pageSize = value;
      this.loading = true;
      this.consumeTimeListByKeyLoad(this.listParam, this.pageSize, this.current);
    },
    // 列表页码切换
    handleCurrentChange: function handleCurrentChange(value) {
      // const this = this;
      this.current = value;
      this.loading = true;
      this.consumeTimeListByKeyLoad(this.listParam, this.pageSize, this.current);
    },
    isShowList: function isShowList(value) {
      var _this2 = this;
      // console.log(value);
      // const this = this;
      this.isList = value;
      this.$nextTick(function () {
        _this2.drawDoughnut();
      });
    },
    // 按时间查询
    getQueryList: function getQueryList(value) {
      // const this = this;
      this.choiceTime = {};
      if (this.doughnutData.length === 0) {
        this.doughnutData = [];
      }
      this.isGetResult = false;
      this.choiceTime.statisType = value.statisType;
      if (value.statisType === 'day') {
        this.choiceTime.dayTime = value.choiceTime;
      } else if (value.statisType === 'month') {
        this.choiceTime.monthMonth = value.choiceTime;
      } else if (value.statisType === 'quarter') {
        this.choiceTime.quarterYear = value.choiceTime;
        this.choiceTime.quarterQuarter = value.quarterQuarter;
      } else if (value.statisType === 'year') {
        this.choiceTime.yearYear = value.choiceTime;
      } else if (value.statisType === 'auto') {
        this.choiceTime.autoStartTime = value.choiceTime.startTime;
        this.choiceTime.autoEndTime = value.choiceTime.endTime;
      }
      this.consumeTimeListLoad(this.choiceTime);
      this.doughnutDataLoad(this.choiceTime);
    },
    // 数据下钻打开弹窗
    isDialogTable: function isDialogTable(row, column) {
      // const this = this;
      this.searchContent = '';
      this.listParam = {};
      this.total = 0;
      if (column.label !== '流程名称' && column.label !== '序号') {
        this.dialogTableVisible = !this.dialogTableVisible;
      }
      this.listParam = {
        processKey: row.processKey
      };
      this.processName = row.processName;
      this.loading = true;
      this.pageSize = 10;
      this.current = 1;
      this.consumeTimeListByKeyLoad(this.listParam, this.pageSize, this.current);
    },
    // 绘制环图
    drawDoughnut: function drawDoughnut() {
      // const this = this;
      if (this.myChart) {
        this.myChart.dispose();
        this.myChart = null;
      }
      if (!this.$refs.processCharts || this.$refs.processCharts.clientWidth === 0) return;
      // 基于准备好的dom，初始化echarts实例
      this.myChart = echarts.init(this.$refs.processCharts);
      this.myChart.setOption(this.doughnutOption);
      this.myChart.off('click');
      this.myChart.on('click', function (param) {
        this.searchContent = '';
        this.listParam = {};
        this.total = 0;
        this.dialogTableVisible = !this.dialogTableVisible;
        this.listParam = {
          processKey: param.data.processKey
        };
        this.processName = param.data.name;
        this.loading = true;
        this.pageSize = 10;
        this.current = 1;
        this.consumeTimeListByKeyLoad(this.listParam, this.pageSize, this.current);
      });
    },
    // 流程消耗时间环图查询
    doughnutDataLoad: function doughnutDataLoad(value) {
      var _this3 = this;
      // const this = this;
      var param = _.cloneDeep(value);
      queryProcessConsumeTime(param).then(function (res) {
        if (res.code === 10000 && res.data && res.data.records.length > 0) {
          _this3.doughnutData = res.data.records;
          _this3.isGetResult = false;
          _this3.$nextTick(function () {
            _this3.drawDoughnut();
          });
        } else {
          _this3.doughnutData = [];
          _this3.isGetResult = true;
        }
      }).catch(function () {
        _this3.$message({
          message: '数据请求失败',
          type: 'error'
        });
      });
    },
    // 流程消耗时间列表查询
    consumeTimeListLoad: function consumeTimeListLoad(value) {
      var _this4 = this;
      // const this = this;
      this.isLoading = true;
      var param = _.cloneDeep(value);
      queryProcessConsumeTime(param).then(function (res) {
        if (res.code === 10000) {
          _this4.isLoading = false;
          _this4.consumeTimeListData = res.data.records;
        }
      }).catch(function () {
        _this4.$message({
          message: '数据请求失败',
          type: 'error'
        });
      });
    },
    // 下钻流程消耗时间列表查询
    consumeTimeListByKeyLoad: function consumeTimeListByKeyLoad(value, size, current) {
      var _this5 = this;
      // const this = this;
      var param = _.cloneDeep(this.choiceTime);
      param.current = current;
      param.size = size;
      param.processKey = value.processKey;
      queryNodeConsumeTimeByProcessKey(param).then(function (res) {
        if (res.code === 10000) {
          _this5.consumeTimeByKeyListData = res.data.records;
          _this5.copyData = res.data.records;
          _this5.total = res.data.total;
          _this5.loading = false;
        }
      }).catch(function () {
        _this5.$message({
          message: '数据请求失败',
          type: 'error'
        });
      });
    }
  }
};
